static void MLOCKED_TEXT stress_run(
	const int32_t ticks_per_sec,
	const uint32_t n_stressors,
	stress_list_item_t *stressors_list,
	double *duration,
	bool *success,
	bool *resource_success,
	bool *metrics_success,
	stress_checksum_t **checksum)
{
	double time_start;
	double time_finish;
	int32_t started_instances = 0;
	const size_t page_size = stress_memory_page_size_get();
	int64_t backoff = DEFAULT_BACKOFF;
	bool handler_set = false;
	stress_pid_t *s_pids_head = NULL;

	time_start = stress_time_now();

	(void)stress_setting_get("backoff", &backoff);

	if (opt_pause) {
		static bool first_run = true;

		if (first_run)
			first_run = false;
		else {
			pr_dbg("pausing for %" PRIu32 " second%s\n", opt_pause,
				opt_pause == 1 ? "" : "s");
			(void)sleep((unsigned int)opt_pause);
		}
	}
	pr_dbg("starting stressor%s\n", n_stressors > 1 ? "s" : "");

	/*
	 *  Work through the list of stressors to run
	 */
	for (g_item_current = stressors_list; g_item_current; g_item_current = g_item_current->next) {
		int32_t j;

		if (g_item_current->ignore.run || g_item_current->ignore.permute) {
			*checksum += g_item_current->instances;
			continue;
		}

		/*
		 *  Each stressor has 1 or more instances to run
		 */
		for (j = 0; j < g_item_current->instances; j++, (*checksum)++) {
			double fork_time_start;
			pid_t pid;
			pid_t child_pid;
			int rc;
			stress_stats_t *const stats = g_item_current->stats[j];

#if defined(STRESS_TERMINATE_PREMATURELY)
			if (g_opt_timeout && (stress_time_now() - time_start > (double)g_opt_timeout))
				goto abort;
#endif
			stress_sync_start_init(&stats->s_pid);
			stats->args.bogo.count.counter_ready = true;
			stats->args.bogo.count.counter = 0;
			stats->checksum = *checksum;
			stats->item = g_item_current;
			stats->s_pid.reaped = false;
			stats->s_pid.wait_status = 0;

			if (g_opt_flags & OPT_FLAGS_DRY_RUN) {
				stats->s_pid.reaped = true;
				stats->s_pid.pid = -1;
				continue;
			}
again:
			if (!stress_continue_flag())
				break;

			stress_memory_compact();

			fork_time_start = stress_time_now();
			pid = fork();
			switch (pid) {
			case -1:
				stats->s_pid.reaped = true;
				if (errno == EAGAIN) {

content.content:
1933						(void)shim_usleep(100000);
1934						goto again;
1935					}
1936					pr_err("cannot fork, errno=%d (%s)\n",
1937						errno, strerror(errno));
1938					stress_stressors_kill(SIGALRM, false);
1939					goto wait_for_stressors;
1940				case 0:
1941					/* Child */
1942					stress_proc_state_set(g_item_current->stressor->name, STRESS_STATE_INIT);
1943					child_pid = getpid();
1944					stats->s_pid.reaped = false;
1945					stats->s_pid.pid = child_pid;
1946					if (g_opt_flags & OPT_FLAGS_C_STATES)
1947						stress_cpuidle_read_cstates_begin(&stats->cstates);
1948					if (g_opt_flags & OPT_FLAGS_IOS)
1949						stress_fs_io_stats_begin(&stats->io_stats);
1950	
1951					stress_make_it_fail_set();
1952	
1953					rc = stress_child_run(checksum,
1954							stats, fork_time_start,
1955							backoff, ticks_per_sec,
1956							j, started_instances,
1957							page_size, child_pid);
1958					if (g_opt_flags & OPT_FLAGS_C_STATES)
1959						stress_cpuidle_read_cstates_end(&stats->cstates);
1960					if (g_opt_flags & OPT_FLAGS_IOS)
1961						stress_fs_io_stats_end(&stats->io_stats);
1962					_exit(rc);
1963				default:
1964					if (pid > -1) {
1965						stats->s_pid.pid = pid;
1966						stats->s_pid.reaped = false;
1967						stats->signalled = false;
1968						started_instances++;
1969	
1970						stress_sync_start_s_pid_list_add(&s_pids_head, &stats->s_pid);
1971						stress_stats_hash_table_add(stats);
1972					}
1973	
1974					/* Forced early abort during startup? */
1975					if (!stress_continue_flag()) {
1976						pr_dbg("abort signal during startup, cleaning up\n");
1977						stress_stressors_kill(SIGALRM, true);
1978						goto wait_for_stressors;
1979					}
1980					break;
1981				}
1982				/*
1983				 *  See if any spawned child processes have
1984				 *  already exited, reap and save their status
1985				 */
1986				(void)stress_child_wait(WNOHANG, success, resource_success, metrics_success);
1987			}
1988		}
1989		if (!handler_set) {
1990			(void)stress_handler_set("stress-ng", false);
1991			handler_set = true;
1992		}
1993	#if defined(STRESS_TERMINATE_PREMATURELY)
1994	abort:
1995	#endif
1996		pr_dbg("%" PRId32 " stressor%s started\n", started_instances,
1997			 started_instances == 1 ? "" : "s");
1998	
1999	wait_for_stressors:
