#  Per stressor x image: time series + coefficient of variation
echo
echo "=== bogo-ops/s time series (per stressor x image) ==="
awk '{
	key = $4 " @" $3
	if (key != prev) {
		if (prev != "") printf "\n"
		printf "%-14s %-18s", $4, $3
		prev = key
	}
	if ($5 == "PASS") printf " %s:%.0f", $1, $6
	else printf " %s:%s", $1, $5
}
END { printf "\n" }' "$tmp/sel"

echo
echo "=== per stressor: mean / coefficient of variation over PASS rates ==="
awk '$5 == "PASS" {
	key = $4
	n[key]++
	sum[key] += $6
	sumsq[key] += $6 * $6
	tags[key] = (tags[key] "" == "" ? $3 : tags[key])
}
END {
	printf "%-14s %8s %10s %8s\n", "stressor", "samples", "mean", "CoV%"
	for (key in n) {
		mean = sum[key] / n[key]
		var = (sumsq[key] - n[key] * mean * mean) / n[key]
		if (var < 0) var = 0
		cov = mean > 0 ? 100 * sqrt(var) / mean : 0
		printf "%-14s %8d %10.0f %7.1f%%\n", key, n[key], mean, cov
	}
}' "$tmp/sel" | sort -k3 -rn

